 302:         // source). See FsTransferSource::open_file for context — join("")
 303:         // can preserve a trailing separator that File::open rejects.
 304:         let full_path = if header.relative_path.is_empty() {
 305:             source_root.to_path_buf()
 306:         } else {
 307:             source_root.join(rel)
 308:         };
 309:         let mut file = std::fs::File::open(&full_path)
 310:             .with_context(|| format!("opening {}", full_path.display()))?;
