 312:         let mut tar_header = Header::new_gnu();
 313:         tar_header.set_entry_type(EntryType::Regular);
 314:         let mode = if header.permissions == 0 {
 315:             0o644
 316:         } else {
 317:             header.permissions
 318:         };
 319:         tar_header.set_mode(mode);
 320:         tar_header.set_size(header.size);
 321:         let mtime = if header.mtime_seconds >= 0 {
 322:             header.mtime_seconds as u64
 323:         } else {
 324:             0
 325:         };
 326:         tar_header.set_mtime(mtime);
